-- Upstream panel PostgreSQL fixture: GoWave column names carrying the upstream types
-- (native enums, uuid, jsonb, timestamptz(3)) plus upstream-only tables and columns.
-- One statement per line, like internal/database/migrations.
CREATE TYPE "USERS_STATUS" AS ENUM ('ACTIVE', 'DISABLED', 'LIMITED', 'EXPIRED');
CREATE TYPE "RESET_PERIODS" AS ENUM ('NO_RESET', 'DAY', 'WEEK', 'MONTH', 'YEAR');
CREATE TYPE "HOST_SECURITY_LAYER" AS ENUM ('DEFAULT', 'TLS', 'NONE');
CREATE TABLE "admin" ("uuid" uuid, "username" varchar(64), "password_hash" varchar(255), "role" varchar(32) DEFAULT 'ADMIN', "created_at" timestamptz(3), "updated_at" timestamptz(3), "telegram_id" bigint);
CREATE TABLE "remnawave_settings" ("id" bigint, "title" varchar(128) DEFAULT 'Upstream Panel', "logo_url" varchar(255), "is_login_allowed" boolean DEFAULT true, "is_register_allowed" boolean DEFAULT false, "password_auth_enabled" boolean DEFAULT true, "passkey_settings" jsonb DEFAULT '{}'::jsonb, "oauth2_settings" jsonb DEFAULT '{}'::jsonb, "password_settings" jsonb DEFAULT '{}'::jsonb, "branding_settings" jsonb DEFAULT '{}'::jsonb);
CREATE TABLE "api_tokens" ("uuid" uuid, "name" text, "expire_at" timestamptz(3), "scopes" text[] DEFAULT '{}', "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "subscription_settings" ("uuid" uuid, "serve_json_at_base_subscription" boolean DEFAULT false, "is_show_custom_remarks" boolean DEFAULT true, "custom_remarks" jsonb DEFAULT '{}'::jsonb, "custom_response_headers" jsonb DEFAULT '{}'::jsonb, "randomize_hosts" boolean DEFAULT false, "response_rules" jsonb DEFAULT '{}'::jsonb, "hwid_settings" jsonb DEFAULT '{}'::jsonb, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "subscription_templates" ("uuid" uuid, "view_position" bigint DEFAULT 0, "name" varchar(255), "tags" text[] DEFAULT '{}', "template_type" varchar(32), "template_yaml" text, "template_json" text, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "subscription_page_config" ("uuid" uuid, "view_position" bigint DEFAULT 0, "name" varchar(255), "tags" text[] DEFAULT '{}', "config" jsonb DEFAULT '{}'::jsonb, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "external_squads" ("uuid" uuid, "view_position" bigint DEFAULT 0, "name" varchar(64), "tags" text[] DEFAULT '{}', "subscription_settings" jsonb DEFAULT '{}'::jsonb, "host_overrides" jsonb DEFAULT '{}'::jsonb, "response_headers_add" jsonb DEFAULT '{}'::jsonb, "response_headers_remove" text[] DEFAULT '{}', "hwid_settings" jsonb DEFAULT '{}'::jsonb, "custom_remarks" jsonb DEFAULT '{}'::jsonb, "subpage_config_uuid" uuid, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "external_squads_templates" ("external_squad_uuid" uuid, "template_type" varchar(32), "template_uuid" uuid);
CREATE TABLE "config_profiles" ("uuid" uuid, "view_position" bigint DEFAULT 1, "name" varchar(64), "tags" text[] DEFAULT '{}', "config" jsonb, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "config_profile_inbounds" ("uuid" uuid, "profile_uuid" uuid, "tag" varchar(64), "type" varchar(32), "network" varchar(32), "security" varchar(32), "port" bigint, "raw_inbound" jsonb);
CREATE TABLE "infra_providers" ("uuid" uuid, "name" varchar(128), "favicon_link" varchar(255), "login_url" varchar(255), "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "infra_billing_nodes" ("uuid" uuid, "node_uuid" uuid, "name" varchar(128), "provider_uuid" uuid, "next_billing_at" timestamptz(3), "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "infra_billing_history" ("uuid" uuid, "provider_uuid" uuid, "amount" numeric(10,2), "billed_at" timestamptz(3));
CREATE TABLE "node_plugin" ("uuid" uuid, "view_position" bigint DEFAULT 0, "name" varchar(255), "tags" text[] DEFAULT '{}', "plugin_config" jsonb DEFAULT '{}'::jsonb, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "nodes" ("id" bigint, "uuid" uuid, "name" varchar(64), "address" varchar(255), "port" bigint DEFAULT 443, "proxy_url" varchar(255), "is_connected" boolean DEFAULT false, "is_connecting" boolean DEFAULT false, "is_disabled" boolean DEFAULT false, "country_code" varchar(8) DEFAULT 'XX', "traffic_limit_bytes" bigint DEFAULT 0, "traffic_used_bytes" bigint DEFAULT 0, "is_traffic_tracking_active" boolean DEFAULT false, "traffic_reset_day" bigint DEFAULT 1, "notify_percent" bigint DEFAULT 80, "view_position" bigint DEFAULT 1, "consumption_multiplier" bigint DEFAULT 1000000000, "node_consumption_multiplier" bigint DEFAULT 1000000000, "tags" text[] DEFAULT '{}', "integration_uuids" uuid[] DEFAULT '{}', "ips" jsonb, "active_config_profile_uuid" uuid, "provider_uuid" uuid, "active_plugin_uuid" uuid, "note" text, "last_status_change" timestamptz(3), "last_status_message" text, "created_at" timestamptz(3), "updated_at" timestamptz(3), "xray_version" varchar(32), "xray_uptime" varchar(32));
CREATE TABLE "users" ("revision" bigint DEFAULT 1, "id" bigint, "short_uuid" varchar(64), "username" varchar(64), "status" "USERS_STATUS", "traffic_limit_bytes" bigint DEFAULT 0, "traffic_limit_strategy" "RESET_PERIODS", "expire_at" timestamptz(3), "last_traffic_reset_at" timestamptz(3), "sub_revoked_at" timestamptz(3), "trojan_password" varchar(64), "vless_uuid" uuid, "ss_password" varchar(64), "description" text, "tag" varchar(64), "telegram_id" bigint, "email" varchar(128), "hwid_device_limit" integer, "external_squad_uuid" uuid, "last_triggered_threshold" bigint DEFAULT 0, "created_at" timestamptz(3), "updated_at" timestamptz(3), "uuid" uuid DEFAULT gen_random_uuid(), "first_connected_at" timestamptz(3));
CREATE TABLE "user_traffic" ("id" bigint, "used_traffic_bytes" bigint DEFAULT 0, "lifetime_used_traffic_bytes" bigint DEFAULT 0, "online_at" timestamptz(3), "last_connected_node_uuid" uuid, "first_connected_at" timestamptz(3));
CREATE TABLE "hosts" ("uuid" uuid, "view_position" bigint DEFAULT 1, "remark" varchar(128), "address" varchar(255), "port" bigint DEFAULT 443, "path" varchar(255), "sni" varchar(255), "host" varchar(255), "alpn" varchar(64), "fingerprint" varchar(64) DEFAULT 'chrome', "security_layer" "HOST_SECURITY_LAYER", "xhttp_extra_params" jsonb, "mux_params" jsonb, "sockopt_params" jsonb, "final_mask" text, "is_disabled" boolean DEFAULT false, "server_description" varchar(255), "vless_route_id" bigint, "pinned_peer_cert_sha256" varchar(255), "verify_peer_cert_by_name" varchar(255), "shuffle_host" boolean DEFAULT false, "mihomo_x25519" boolean DEFAULT false, "mihomo_ip_version" varchar(32), "xray_json_template_uuid" uuid, "keep_sni_blank" boolean DEFAULT false, "exclude_from_subscription_types" text[] DEFAULT '{}', "mapper" jsonb DEFAULT '{}'::jsonb, "internal_squads_mode" varchar(32) DEFAULT 'EXCLUDE', "tags" text[] DEFAULT '{}', "is_hidden" boolean DEFAULT false, "override_sni_from_address" boolean DEFAULT false, "config_profile_uuid" uuid, "config_profile_inbound_uuid" uuid, "allow_insecure" boolean DEFAULT false);
CREATE TABLE "hosts_to_nodes" ("host_uuid" uuid, "node_uuid" uuid);
CREATE TABLE "internal_squads" ("uuid" uuid, "view_position" bigint DEFAULT 0, "name" varchar(64), "tags" text[] DEFAULT '{}', "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "internal_squad_members" ("internal_squad_uuid" uuid, "user_id" bigint);
CREATE TABLE "internal_squad_inbounds" ("internal_squad_uuid" uuid, "inbound_uuid" uuid);
CREATE TABLE "internal_squad_host_links" ("host_uuid" uuid, "squad_uuid" uuid);
CREATE TABLE "config_profile_inbounds_to_nodes" ("config_profile_inbound_uuid" uuid, "node_uuid" uuid);
CREATE TABLE "hwid_user_devices" ("hwid" varchar(128), "user_id" bigint, "platform" varchar(64), "os_version" varchar(64), "device_model" varchar(128), "user_agent" text, "request_ip" varchar(64), "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "nodes_usage_history" ("node_uuid" uuid, "created_at" timestamptz(3), "download_bytes" bigint, "upload_bytes" bigint, "total_bytes" bigint, "updated_at" timestamptz(3));
CREATE TABLE "nodes_user_usage_history" ("node_id" bigint, "created_at" timestamptz(3), "user_id" bigint, "total_bytes" bigint, "updated_at" timestamptz(3));
CREATE TABLE "user_subscription_request_history" ("id" bigint, "user_id" bigint, "request_ip" varchar(64), "user_agent" text, "srr_rule_name" varchar(128), "srr_response_type" varchar(64) DEFAULT 'UNKNOWN', "request_at" timestamptz(3));
CREATE TABLE "integrations" ("uuid" uuid, "name" varchar(30), "description" varchar(255), "config" jsonb, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "entity_meta" ("entity_id" varchar(64), "entity_type" varchar(32), "metadata" jsonb DEFAULT '{}'::jsonb);
CREATE TABLE "config_profile_snippets" ("name" varchar(255), "snippet" jsonb DEFAULT '{}'::jsonb, "created_at" timestamptz(3));
CREATE TABLE "shared_lists" ("name" varchar(255), "config" jsonb DEFAULT '{}'::jsonb, "created_at" timestamptz(3), "updated_at" timestamptz(3));
CREATE TABLE "_prisma_migrations" ("id" varchar(36), "checksum" varchar(64), "migration_name" varchar(255), "finished_at" timestamptz(3), "applied_steps_count" integer DEFAULT 0);
